code.cpp:
class Solution {
public:
    bool areSimilar(vector<vector<int>>& mat, int k) {
        int m = mat.size();
        int n = mat[0].size();
        k %= n;
        for (int row = 0; row < m; row++) {
            for (int col = 0; col < n; col++) {
                int target;
                if (row % 2 == 0) {
                    target = (col + k) % n;
                } else {
                    target = (col - k + n) % n;
                }
                if (mat[row][col] != mat[row][target]) {
                    return false;
                }
            }
        }
        return true;
    }
};
